# ruff: noqa: INP001, PLR2004 -- source namespace and binary protocol
"""SQ FUTURES historical source under explicit host lifecycle.

Description:
    Owner-script DAT decoding, symbol routing and canonical conversion; host
    owns network credentials, jobs and immutable historical partitions.
Purpose:
    FEAT-DM-SQ_FUTURES: Script-backed historical data integration.
Key Capabilities:
    - FR-SQ-FUTURES-CATALOG: Source snapshot search; logs operation requests.
    - FR-SQ-FUTURES-DECODE: DAT numeric semantics; logs decoded rows.
    - FR-SQ-FUTURES-PUBLISH: Source acquisition; logs committed partitions.
Python API Usage:
    contribution = await prepare(capabilities)
    result = await contribution.invoke("catalog", {})
CLI Usage:
    uv run pytest tests/plugin/DataSource/test_sq_sources.py --no-cov
"""

